#include <iostream>

int main()
{
    int n{};
    if (!(std::cin >> n)) return 0;

    for (int i = 1; i <= n; ++i)
    {
        bool by3{ i % 3 == 0 };
        bool by5{ i % 5 == 0 };

        if (by3 && by5)
            std::cout << "both\n";
        else if (by3)
            std::cout << "three\n";
        else if (by5)
            std::cout << "five\n";
        else
            std::cout << i << "\n";
    }

    return 0;
}
